import { Listen, customElement, html, nextrap_element, nothing, property, state, unsafeCSS } from '@nextrap/nt-core';
import { resetStyle } from '@nextrap/style-reset';
import { waitForPreVisual } from '@trunkjs/browser-utils';

import { PropertyValues } from 'lit';
import { parseInputOptions, serializeInputOptions } from '../../lib/options';
import type { NteInputPluginClass, NteInputPluginInterface, NteInputPluginStyleSheet } from '../../lib/plugin';
import {
  NTE_INPUT_CONTROL_ID,
  type InputOptionsType,
  type NteInputRenderContext,
  type NteInputValue,
} from '../../lib/types';
import style from './nte-input.scss?inline';

@customElement('nte-input')
export class NteInput extends nextrap_element({
  eventBinding: true,
  slotVisibility: true, // This will add .slot-empty to empty slot elements. Rely on this to detect empty slots in css.
}) {
  static formAssociated = true;
  static override styles = [unsafeCSS(style), unsafeCSS(resetStyle)];

  private static readonly plugins = new Map<string, NteInputPluginClass>();

  @property({ type: String, reflect: true }) accessor type = 'text';
  // Reflektiert explizite Labels, erzeugt aber beim Initialisieren kein fehlendes label-Attribut.
  @property({ type: String, reflect: true, useDefault: true }) accessor label = '';
  // Status-Texte des Switches bleiben unabhängig vom festen Formular-Label reaktiv.
  @property({ type: String, attribute: 'on-text' }) accessor onText = '';
  @property({ type: String, attribute: 'off-text' }) accessor offText = '';
  @property({ type: String }) accessor placeholder = '';
  @property({
    attribute: 'data-options',
    converter: {
      fromAttribute: (value: string | null) => parseInputOptions(value),
      toAttribute: (value: InputOptionsType) => serializeInputOptions(value),
    },
  })
  accessor options: InputOptionsType | null = null;
  @property({ type: Boolean }) accessor multiple = false;
  // Beobachtet Sperrzustände, damit auch nachträgliche Attributänderungen die Plugins neu rendern.
  @property({ type: Boolean, reflect: true }) accessor disabled = false;
  @property({ type: Boolean, attribute: 'readonly', reflect: true }) accessor readOnly = false;
  @property({ type: String, attribute: 'validation-message', reflect: true }) accessor validationMessage = '';
  @property({ type: Boolean, reflect: true }) accessor invalid = false;
  @property({ type: Boolean, reflect: true }) accessor valid = false;
  @property({ type: Boolean, reflect: true, attribute: 'has-value' }) accessor hasValue = false;
  @property({ type: Boolean, reflect: true, attribute: 'has-placeholder' }) accessor hasPlaceholder = false;
  @property({ type: Boolean, reflect: true, attribute: 'hoverlabel-active' }) accessor hoverlabelActive = false;

  @state()
  protected accessor _value: NteInputValue | undefined = undefined;

  @state()
  protected accessor _labelFor: string = NTE_INPUT_CONTROL_ID;

  #plugin?: NteInputPluginInterface;
  #pluginStyleElement?: HTMLStyleElement;
  #pluginConstructableStyleSheet?: CSSStyleSheet;
  #internals: ElementInternals | null = null;

  constructor() {
    super();

    if (typeof this.attachInternals === 'function') {
      this.#internals = this.attachInternals();
    }
  }

  static registerPlugin(pluginClass: NteInputPluginClass) {
    for (const rawType of pluginClass.types) {
      const type = rawType.trim().toLowerCase();

      if (!type) {
        continue;
      }

      if (this.plugins.has(type)) {
        throw new Error(`Plugin for input type "${type}" is already registered.`);
      }

      this.plugins.set(type, pluginClass);
    }
  }

  static getPlugin(type: string) {
    return this.plugins.get(type.trim().toLowerCase());
  }

  override async connectedCallback() {
    await waitForPreVisual();

    const pluginClass = NteInput.getPlugin(this.#normalizedType);

    if (!pluginClass) {
      throw new Error(`No plugin for type ${this.#normalizedType}`);
    }
    this.#plugin = new pluginClass(this);

    if (this._value === undefined) {
      this._value = this.#plugin?.getInitValue();
    }

    if (this.#willValidate() && typeof this.#internals?.setValidity === 'function') {
      this.#internals.setValidity({ customError: true, badInput: true }, 'Invalid value');
    }

    super.connectedCallback();

    this.#applyPluginStyleSheet(this.#plugin.getStyleSheet());
    this.#plugin?.connected();
  }

  override disconnectedCallback() {
    super.disconnectedCallback();
    this.#plugin?.disconnected();
  }

  // Exposes the form-associated validity contract so tj-form can validate this custom control before submit.
  checkValidity(): boolean {
    if (this.disabled || this.readOnly) return true;
    return this.#internals?.checkValidity() ?? this.#plugin?.isValid() ?? true;
  }

  // Reports the native validation state and lets the browser display the control's validation feedback.
  reportValidity(): boolean {
    if (this.disabled || this.readOnly) return true;
    return this.#internals?.reportValidity() ?? this.#plugin?.isValid() ?? true;
  }

  override attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null) {
    super.attributeChangedCallback(name, oldValue, newValue);
    this.#plugin?.onHostAttributeChange(name, oldValue, newValue);
  }

  override updated(changedProperties: Map<PropertyKey, unknown>) {
    super.updated(changedProperties);
    this.#plugin?.updated(changedProperties);
    this.syncPluginState();

    // Entfernt veraltete Fehler beim Sperren und prüft entsperrte Pflichtfelder erneut.
    if (changedProperties.has('disabled') || changedProperties.has('readOnly')) {
      if (this.disabled || this.readOnly) {
        this.#internals?.setValidity?.({});
        this.invalid = false;
        this.valid = false;
      } else if (changedProperties.get('disabled') === true || changedProperties.get('readOnly') === true) {
        this.onMustRevalidateInternal();
      }
    }
  }

  override render() {
    const plugin = this.#plugin;
    const isHoverLabel = this.classList.contains('hoverlabel');

    const pluginHtml = plugin?.render(this.renderContext);
    const labelTemplate = html`
      <label id="label" part="label" for=${this._labelFor} ?hidden=${(!this.label && !this.hasAttribute('label')) || Boolean(plugin?.isLabelHidden())}>
        ${this.label}
      </label>
    `;

    return html`
      <div id="wrapper" part="wrapper">
        <div id="field" part="field">
          ${isHoverLabel || Boolean(plugin?.isLabelHidden())
            ? nothing
            : html`
                <div id="label-area" part="label-area" ?hidden=${!this.label && !this.hasAttribute("label")}>
                  ${labelTemplate}
                  <button
                    id="description-trigger"
                    part="description-trigger"
                    type="button"
                    aria-label="Beschreibung zu ${this.label}"
                    aria-haspopup="true"
                    aria-controls="description-popover"
                    popovertarget="description-popover"
                    @click=${(event: Event) => event.stopPropagation()}
                    @pointerenter=${this.onDescriptionEnter}
                    @pointerleave=${this.onDescriptionLeave}
                  >ⓘ</button>
                  <div
                    id="description-popover"
                    part="description-popover"
                    popover="auto"
                    role="note"
                    @pointerenter=${this.onDescriptionEnter}
                    @pointerleave=${this.onDescriptionLeave}
                  ><slot id="description-slot" name="description"></slot></div>
                </div>
              `}

          <div id="control-shell" part="control">
            <slot id="start" name="start" part="start"></slot>
            <div id="control" part="control-inner">
              ${isHoverLabel ? labelTemplate : nothing}
              <div id="control-input" part="control-input">${pluginHtml ?? nothing}</div>
            </div>
            <slot id="end" name="end" part="end"></slot>
          </div>
        </div>

        <div id="validation" part="validation" aria-live="polite">
          <div id="validation-inner" part="validation-inner">
            <div id="validation-bubble" part="validation-bubble">
              <span id="validation-arrow" part="validation-arrow" aria-hidden="true"></span>
              <div id="validation-content" part="validation-content">
                <slot name="validation">${this.validationMessage}</slot>
              </div>
            </div>
          </div>
        </div>

        <div id="input-aid" part="input-aid">
          <div id="input-aid-inner" part="input-aid-inner">
            <div id="input-aid-bubble" part="input-aid-bubble">
              <span id="input-aid-arrow" part="input-aid-arrow" aria-hidden="true"></span>
              <div id="input-aid-content" part="input-aid-content">
                <slot name="input-aid"></slot>
              </div>
            </div>
          </div>
        </div>
      </div>
    `;
  }

  protected override update(changedProperties: PropertyValues) {
    // Plugins lesen Host-Attribute im render(); Lit reflektiert Properties erst danach.
    // Synchronisiert deshalb Sperrzustände vorab, auch beim Entsperren per JavaScript.
    if (changedProperties.has('disabled')) {
      this.toggleAttribute('disabled', this.disabled);
    }
    if (changedProperties.has('readOnly')) {
      this.toggleAttribute('readonly', this.readOnly);
    }
    super.update(changedProperties);
  }

  get renderContext(): NteInputRenderContext {
    return {
      element: this,
      type: this.#normalizedType,
    };
  }

  get form() {
    return this.#internals?.form ?? null;
  }

  get name() {
    return this.getAttribute('name') ?? '';
  }

  get value(): NteInputValue {
    return this._value;
  }

  set value(value: NteInputValue) {
    this._value = value;
    this.syncPluginState();
  }

  get selectedOptions(): InputOptionsType {
    return this.#plugin?.getSelectedOptions() ?? [];
  }

  syncPluginState() {
    const plugin = this.#plugin;

    this.hasValue = plugin?.hasValue() ?? false;
    this.hasPlaceholder = plugin?.hasPlaceholder() ?? this.hasAttribute('placeholder');
    this.hoverlabelActive = plugin?.isHoverlabelActive() ?? false;
    this._labelFor = plugin?.getLabelFor() ?? NTE_INPUT_CONTROL_ID;
    this.#syncFormValue();
  }

  formResetCallback() {
    this.#plugin?.formResetCallback();
    this.syncPluginState();
  }

  formDisabledCallback(disabled: boolean) {
    this.#plugin?.formDisabledCallback(disabled);
    this.syncPluginState();
  }

  #syncFormValue() {
    if (!this.#internals || typeof this.#internals.setFormValue !== 'function') {
      return;
    }

    if (!this.name || this.hasAttribute('disabled')) {
      this.#internals.setFormValue(null);
      return;
    }

    this.#internals.setFormValue(this.#plugin?.getFormValue() ?? null);
  }

  @Listen('input', { target: 'host' })
  @Listen('invalid', { target: 'host' })
  onMustRevalidateInternal() {
    if (!this.#willValidate()) {
      return;
    }
    if (this.#plugin?.isValid() === true) {
      if (typeof this.#internals?.setValidity === 'function') {
        this.#internals.setValidity({});
      }
      this.removeAttribute('invalid');
      this.setAttribute('valid', '');
    } else {
      if (typeof this.#internals?.setValidity === 'function') {
        this.#internals.setValidity({ customError: true, badInput: true }, 'Invalid value');
      }
      this.setAttribute('invalid', '');
      this.removeAttribute('valid');
    }
  }

  // Hover öffnet dieselbe native Popover-Fläche wie ein Klick auf den Info-Button.
  onDescriptionEnter() {
    const popover = this.renderRoot.querySelector<HTMLElement>('#description-popover');
    if (popover && !popover.matches(':popover-open') && popover.querySelector('slot')?.assignedNodes().length) {
      popover.showPopover();
    }
  }

  // Beim Verlassen des Info-Bereichs wird die Hover-Hilfe geschlossen.
  onDescriptionLeave(event: PointerEvent) {
    const trigger = this.renderRoot.querySelector<HTMLElement>('#description-trigger');
    const popover = this.renderRoot.querySelector<HTMLElement>('#description-popover');
    const next = event.relatedTarget;
    if (next instanceof Node && (trigger?.contains(next) || popover?.contains(next))) return;
    if (popover?.matches(':popover-open')) popover.hidePopover();
  }

  @Listen('click')
  onClick(e: Event) {
    if (this.hasAttribute('disabled')) {
      return;
    }
    this.#plugin?.onClick(e);
    this.#plugin?.getFormElement()?.focus();
  }

  // Native change-Events verlassen den Shadow DOM nicht; bereits composed Events bleiben unverändert.
  @Listen('change', { target: 'shadowRoot' })
  onShadowChange(e: Event) {
    if (e.composed || this.disabled || this.readOnly) return;
    this.dispatchEvent(new Event('change', { bubbles: true, composed: true }));
  }

  @Listen('change')
  onChange(e: Event) {
    // Gesperrte Controls dürfen ihren Formularwert nicht durch UI-Ereignisse ändern.
    if (this.disabled || this.readOnly) return;
    this.#plugin?.onChange(e);
  }

  // Capture synchronisiert den Wert vor Validierung und externen Bubble-Listenern am Host.
  @Listen('input', { options: { capture: true } })
  onInput(e: Event) {
    // Programmatische value-Zuweisungen bleiben auch bei gesperrter Benutzereingabe möglich.
    if (this.disabled || this.readOnly) return;
    this.#plugin?.onInput(e);
  }

  #willValidate() {
    if (this.hasAttribute('required') && !this.hasAttribute('disabled') && !this.hasAttribute('readonly')) {
      return true;
    }
    return false;
  }

  #applyPluginStyleSheet(styleSheet: NteInputPluginStyleSheet | null) {
    const renderRoot = this.renderRoot;

    if (!(renderRoot instanceof ShadowRoot)) {
      return;
    }

    if (this.#pluginConstructableStyleSheet && 'adoptedStyleSheets' in renderRoot) {
      renderRoot.adoptedStyleSheets = renderRoot.adoptedStyleSheets.filter(
        (sheet) => sheet !== this.#pluginConstructableStyleSheet,
      );
      this.#pluginConstructableStyleSheet = undefined;
    }

    this.#pluginStyleElement?.remove();
    this.#pluginStyleElement = undefined;

    if (!styleSheet) {
      return;
    }

    if (
      typeof CSSStyleSheet !== 'undefined' &&
      styleSheet instanceof CSSStyleSheet &&
      'adoptedStyleSheets' in renderRoot
    ) {
      renderRoot.adoptedStyleSheets = [...renderRoot.adoptedStyleSheets, styleSheet];
      this.#pluginConstructableStyleSheet = styleSheet;
      return;
    }

    const styleElement = document.createElement('style');
    styleElement.setAttribute('data-plugin-style', this.#normalizedType);
    styleElement.textContent =
      typeof styleSheet === 'string' ? styleSheet : Array.from(styleSheet.cssRules, (rule) => rule.cssText).join('\n');

    renderRoot.append(styleElement);
    this.#pluginStyleElement = styleElement;
  }

  get #normalizedType() {
    return this.type.trim().toLowerCase() || 'text';
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'nte-input': NteInput;
  }
}
